package com.example.vitalwearclonev1.gridbattle

/**
 * Battle-chip library for Grid Battle mode (2026-09-25).
 *
 * ~150 chips with original names across 10 families: Blasters, Blades,
 * Launchers, Beams, Storms, Summons, Traps, Supports, Cannons, Seekers.
 * Tiers: 115 STANDARD / 25 MEGA / 10 GIGA.
 *
 * Letter codes enable folder code-matching (same code or '*' wildcard).
 * Damage is per hit; multiply by [hits] for multi-hit totals.
 * Exact balance numbers are tuned in the playtest pass - treat these
 * as the starting feel, not the final word.
 */
enum class ChipTier { STANDARD, MEGA, GIGA }

enum class ChipElement { FIRE, WATER, ELEC, WOOD, SWORD, WIND, CURSOR, BREAK, PLUS, NULL }

enum class EffectKind { PROJECTILE, MELEE, LOB, BEAM, SUMMON, TRAP, SUPPORT, SWORD }

data class BattleChip(
    val id: Int,
    val name: String,
    val tier: ChipTier,
    val element: ChipElement,
    val damage: Int,
    val codes: List<Char>,
    val mb: Int,
    val hits: Int = 1,
    val effectKind: EffectKind,
    val description: String
)

