    fun byId(id: Int): BattleChip? = chips.find { it.id == id }

    fun byTier(tier: ChipTier): List<BattleChip> = chips.filter { it.tier == tier }

    fun byElement(element: ChipElement): List<BattleChip> = chips.filter { it.element == element }
